"""Calculate monthly cleaning-service payroll from the supplied CSV files."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _rows(filename: str) -> list[dict[str, str]]:
    with (DATASET / filename).open(newline="", encoding="utf-8-sig") as file:
        return list(csv.DictReader(file))


def _first_weekday(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_start(workday: date, weekday: int) -> date:
    start = _first_weekday(workday.year, workday.month, weekday)
    if workday >= start:
        return start
    previous_month_last_day = workday.replace(day=1) - timedelta(days=1)
    return _first_weekday(
        previous_month_last_day.year, previous_month_last_day.month, weekday
    )


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _rows("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _rows("tasks.csv")
    }

    # An id may differ while every other field is identical. These are
    # duplicate timesheet entries and represent one shift.
    unique_shifts = {}
    for row in _rows("timesheet.csv"):
        if row["employee_id"] not in employees:
            continue
        try:
            workday = date.fromisoformat(row["date"])
        except ValueError:
            continue
        hours = Decimal(row["hours_worked"])
        if hours < 0 or hours > 24:
            continue
        key = tuple(value for field, value in row.items() if field != "id")
        unique_shifts[key] = (row, workday, hours)

    shifts = list(unique_shifts.values())
    if not shifts:
        return {pesel: [] for pesel in employees}
    billing_weekday = min(workday for _, workday, _ in shifts).weekday()

    totals: dict[str, dict[date, Decimal]] = defaultdict(
        lambda: defaultdict(Decimal)
    )
    for row, workday, hours in shifts:
        pesel = row["employee_id"]
        billing_month = _billing_start(workday, billing_weekday)
        # The bonus field can include payments for unknown task IDs or
        # erroneous negative amounts. Derive it from known completed tasks.
        task_ids = (int(value) for value in re.findall(r"\d+", row["performed_tasks"]))
        bonus = sum((task_pay.get(task_id, Decimal(0)) for task_id in task_ids), Decimal(0))
        totals[pesel][billing_month] += hours * employees[pesel] + bonus

    return {
        pesel: [
            int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for _, amount in sorted(totals[pesel].items())
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as output:
        json.dump(answer(), output)

